// ============================================================
// Nail Studio Kyiv OB — Prepare Context for AI Operator
// Fetches client, services, masters, bookings from Supabase
// Builds system prompt with full business context
// ============================================================

const SUPABASE_URL = '__SUPABASE_URL__';
const SUPABASE_KEY = '__SUPABASE_SERVICE_ROLE_KEY__';
const ACCESS_TOKEN = '__INSTAGRAM_ACCESS_TOKEN__';

// --- Extract message data ---
const entry = $input.first().json.body.entry[0];
const messaging = entry.messaging[0];
const senderId = messaging.sender.id;
const messageObj = messaging.message;
const messageText = (messageObj.text || '').trim();

// --- Supabase REST helpers ---
async function supabaseGet(table, query = '') {
  return await helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/${table}?${query}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    }
  });
}

async function supabasePost(table, data) {
  return await helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/${table}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: data
  });
}

async function supabasePatch(table, query, data) {
  return await helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/${table}?${query}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: data
  });
}

// --- Fetch Instagram user profile ---
async function getInstagramProfile(userId) {
  try {
    return await helpers.httpRequest({
      method: 'GET',
      url: `https://graph.instagram.com/v21.0/${userId}?fields=name,username&access_token=${ACCESS_TOKEN}`,
      headers: { 'Content-Type': 'application/json' }
    });
  } catch (e) {
    return {};
  }
}

// --- Get or create client ---
let clients = await supabaseGet('clients', `instagram_id=eq.${senderId}`);
let client;
if (clients.length === 0) {
  const profile = await getInstagramProfile(senderId);
  const created = await supabasePost('clients', {
    instagram_id: senderId,
    instagram_username: profile.username || null,
    name: profile.name || null,
    last_visit: new Date().toISOString()
  });
  client = Array.isArray(created) ? created[0] : created;
} else {
  client = clients[0];
  const updates = { last_visit: new Date().toISOString() };
  if (!client.instagram_username || !client.name) {
    const profile = await getInstagramProfile(senderId);
    if (profile.username && !client.instagram_username) updates.instagram_username = profile.username;
    if (profile.name && !client.name) updates.name = profile.name;
  }
  await supabasePatch('clients', `id=eq.${client.id}`, updates);
}

// --- Fetch business data ---
const services = await supabaseGet('services', 'is_active=eq.true&order=category.asc,price.asc');
const masters = await supabaseGet('masters', 'is_active=eq.true');
const masterServices = await supabaseGet('master_services', 'select=master_id,service_id');

// --- Fetch today's date (Kyiv) ---
const now = new Date();
const kyivFormatter = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' });
const today = kyivFormatter.format(now);

// --- Fetch available dates per master ---
const allFreeSlots = await supabaseGet('schedule_slots',
  `is_booked=eq.false&date=gte.${today}&order=master_id.asc,date.asc&select=master_id,date`);

const availableDates = {};
for (const slot of allFreeSlots) {
  if (!availableDates[slot.master_id]) availableDates[slot.master_id] = new Set();
  availableDates[slot.master_id].add(slot.date);
}

// --- Fetch client's active bookings ---
const bookings = await supabaseGet('bookings',
  `client_id=eq.${client.id}&status=eq.confirmed&date=gte.${today}&select=id,date,start_time,service_id(name,price),master_id(name)&order=date.asc,start_time.asc`);

// --- Build master-service mapping ---
const masterServiceMap = {};
for (const ms of masterServices) {
  if (!masterServiceMap[ms.master_id]) masterServiceMap[ms.master_id] = [];
  masterServiceMap[ms.master_id].push(ms.service_id);
}

// --- Build service list ---
let servicesList = '';
services.forEach(s => {
  servicesList += `  💅 ID: ${s.id} | ${s.name} | ${s.category} | ${s.price} грн | ${s.duration_minutes} хв\n`;
});

// --- Build masters list ---
let mastersList = '';
masters.forEach(m => {
  const svcIds = masterServiceMap[m.id] || [];
  const svcNames = svcIds.map(sid => {
    const svc = services.find(s => s.id === sid);
    return svc ? svc.name : '';
  }).filter(Boolean).join(', ');
  const dates = [...(availableDates[m.id] || [])].slice(0, 10).join(', ');
  mastersList += `  - ID: ${m.id} | ${m.name} | Послуги: ${svcNames} | Вільні дати: ${dates || 'немає'}\n`;
});

// --- Build bookings list ---
let bookingsList = '';
if (bookings.length > 0) {
  bookings.forEach(b => {
    const svcName = b.service_id?.name || 'Послуга';
    const masterName = b.master_id?.name || 'Майстер';
    const time = (b.start_time || '').substring(0, 5);
    bookingsList += `  - ID: ${b.id} | ${svcName} у ${masterName}, ${b.date} о ${time}\n`;
  });
} else {
  bookingsList = '  Немає активних записів.\n';
}

const systemPrompt = `Ти — AI-адміністратор nail-студії "Nail Studio" (@nail.studio.kyiv_ob) 💅. Ти спілкуєшся з клієнтами через Instagram Direct.

# ПРО СТУДІЮ
- Назва: Nail Studio
- Instagram: @nail.studio.kyiv_ob
- Локація: Київська область
- Спеціалізація: манікюр, педикюр, нарощування нігтів, дизайн
- Графік: Пн-Сб 9:00-18:00, Нд — вихідний

# ПРАВИЛА
1. Відповідай ТІЛЬКИ українською мовою.
2. Будь привітним, ввічливим та професійним.
3. Використовуй емоджі: 💅 нігті, 💰 ціни, 📅 дати, ⏰ час, ✅ підтвердження, ❌ скасування, 🌸 студія, 👋 привітання, 💕 задоволення
4. Не вигадуй інформацію. Користуйся тільки даними нижче та інструментами.
5. Відповідай коротко — це Instagram чат.
6. Не використовуй markdown-форматування — Instagram їх не підтримує.
7. Максимальна довжина відповіді — 900 символів.

# ПОСЛУГИ
${servicesList}
# МАЙСТРИ
${mastersList}
# АКТИВНІ ЗАПИСИ КЛІЄНТА
${bookingsList}
# ДАНІ КЛІЄНТА
- Client Instagram ID: ${senderId}
- Імʼя: ${client.name || 'невідомо'}
- Instagram: @${client.instagram_username || 'невідомо'}

# СЬОГОДНІ
${today} (часовий пояс Europe/Kyiv)

# ЯК ЗАПИСАТИ КЛІЄНТА
1. Зʼясуй яка послуга потрібна.
2. Допоможи обрати майстра.
3. Використай find_available_times щоб перевірити вільний час.
4. Запропонуй вільні години.
5. Коли клієнт підтвердив — використай create_booking.
6. Після бронювання повідом клієнта (запис також автоматично зʼявиться в Google Calendar студії).

# СКАСУВАННЯ
Якщо клієнт хоче скасувати — використай cancel_booking з ID запису.

# КНОПКИ
В кінці КОЖНОГО повідомлення додавай:
[BUTTONS: Кнопка 1 | Кнопка 2 | Кнопка 3]
Максимум 13 кнопок, кожна до 20 символів.

Приклади:
- Привітання: [BUTTONS: 💅 Манікюр | 🦶 Педикюр | 💎 Нарощування | 🎨 Дизайн | 💰 Прайс]
- Вибір послуги: [BUTTONS: Класичний | Апаратний | +Гель-лак | ⬅️ Назад]
- Підтвердження: [BUTTONS: ✅ Підтверджую | ❌ Скасувати]
- Після запису: [BUTTONS: 📋 Мої записи | 💅 Ще запис | 💰 Прайс]`;

return [{
  json: {
    userMessage: messageText,
    systemPrompt: systemPrompt,
    senderId: senderId,
    clientId: client.id,
    clientInstagramId: senderId,
    accessToken: ACCESS_TOKEN
  }
}];

