// ============================================================
// Format AI response for Instagram DM
// Parses [BUTTONS: ...] tags into Instagram quick_replies
// ============================================================

const aiOutput = $json.output || 'Вибачте, сталася помилка. Спробуйте ще раз.';
const prepareData = $('Prepare Context').first().json;
const senderId = prepareData.senderId;
const accessToken = prepareData.accessToken;

// --- Parse [BUTTONS: btn1 | btn2 | btn3] from AI output ---
let replyText = aiOutput;
let quickReplies = [];

const buttonMatch = replyText.match(/\[BUTTONS:\s*(.+?)\]/);
if (buttonMatch) {
  replyText = replyText.replace(/\[BUTTONS:\s*.+?\]/, '').trim();
  const buttons = buttonMatch[1].split('|').map(b => b.trim()).filter(b => b.length > 0);
  quickReplies = buttons.slice(0, 13).map(label => {
    const trimmedLabel = label.substring(0, 20);
    return {
      content_type: 'text',
      title: trimmedLabel,
      payload: trimmedLabel
    };
  });
}

if (replyText.length > 950) {
  replyText = replyText.substring(0, 947) + '...';
}

const messagePayload = { text: replyText };
if (quickReplies.length > 0) {
  messagePayload.quick_replies = quickReplies;
}

return [{
  json: {
    senderId: senderId,
    messagePayload: messagePayload,
    accessToken: accessToken
  }
}];

